export class CdpBluetoothEmulation{#t;constructor(t){this.#t=t}async emulateAdapter(t,e=!0){await this.#t.send("BluetoothEmulation.disable"),await this.#t.send("BluetoothEmulation.enable",{state:t,leSupported:e})}async disableEmulation(){await this.#t.send("BluetoothEmulation.disable")}async simulatePreconnectedPeripheral(t){await this.#t.send("BluetoothEmulation.simulatePreconnectedPeripheral",t)}}